css:
:root { image-rendering: pixelated; }
.shell :is(.rumahl-window-surface, .rumahl-app-surface, .rumahl-settings, .rumahl-group, .rumahl-sidenav, .rumahl-window, .rumahl-menu, .rumahl-popover, .rumahl-tray, [data-floating], .btn, input, select, textarea, button) { border-radius: 0 !important; }
.shell :is(.rumahl-window-surface, .rumahl-app-surface, .rumahl-settings) { background: #12122a !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; border: 2px solid #3a3a6e !important; box-shadow: 6px 6px 0 0 rgba(0,0,0,0.7) !important; }
.shell :is(.rumahl-group, .btn, input, select, textarea) { border-width: 2px !important; box-shadow: 3px 3px 0 0 rgba(0,0,0,0.55) !important; }
.shell .rumahl-group { background: #16162f !important; }
.shell :focus-visible { outline: 3px solid #39ff14 !important; outline-offset: 2px !important; }
.shell :is(h1, h2, h3, strong, button, .rumahl-sidenav__label) { letter-spacing: 0.02em; }
